# ============================================================
# CELL 17M - SELF-CONTAINED HTML VISUAL AUDIT REPORT
#
# Input:
#   confidence_threshold_analysis_extended/
#       error_visualizations/
#       visual_overlay_manifest.csv
#       visual_audit_image_class_summary.csv
#       visual_audit_object_details.csv
#       visual_audit_fp_breakdown.csv
#       selected_visual_error_examples.csv
#
# Output:
#   visual_error_audit_report.html
#   visual_error_audit_notes.txt
#
# Features:
#   1. All overlay images embedded as Base64.
#   2. No external internet dependency.
#   3. Filter by model, class and split.
#   4. Search by image filename.
#   5. Click image to enlarge.
#   6. Download individual overlay image.
#   7. Dataset-level class error summary.
#   8. FP category breakdown.
#   9. Export compact text notes.
#
# No YOLO inference.
# No GPU required.
# ============================================================


# ============================================================
# 1. IMPORTS
# ============================================================

import os
import re
import base64
import html as html_lib
import json

import numpy as np
import pandas as pd

from pathlib import Path

from IPython.display import display, FileLink


# ============================================================
# 2. PATHS
# ============================================================

ROOT = Path(
    "/kaggle/working/YOLO11_seg_expanded"
)

SOURCE_DIR = (
    ROOT
    / "research_experiments"
    / "confidence_threshold_analysis_extended"
)

VISUAL_DIR = (
    SOURCE_DIR
    / "error_visualizations"
)

REPORT_DIR = (
    SOURCE_DIR
    / "html_visual_audit"
)

REPORT_DIR.mkdir(
    parents=True,
    exist_ok=True
)


MANIFEST_PATH = (
    SOURCE_DIR
    / "visual_overlay_manifest.csv"
)

AUDIT_SUMMARY_PATH = (
    SOURCE_DIR
    / "visual_audit_image_class_summary.csv"
)

AUDIT_DETAILS_PATH = (
    SOURCE_DIR
    / "visual_audit_object_details.csv"
)

FP_BREAKDOWN_PATH = (
    SOURCE_DIR
    / "visual_audit_fp_breakdown.csv"
)

SELECTED_PATH = (
    SOURCE_DIR
    / "selected_visual_error_examples.csv"
)


REPORT_PATH = (
    REPORT_DIR
    / "visual_error_audit_report.html"
)

NOTES_PATH = (
    REPORT_DIR
    / "visual_error_audit_notes.txt"
)


# ============================================================
# 3. VERIFY INPUT FILES
# ============================================================

print("=" * 80)
print("1. VERIFY INPUT FILES")
print("=" * 80)

required_files = [
    MANIFEST_PATH,
    AUDIT_SUMMARY_PATH,
    AUDIT_DETAILS_PATH,
    FP_BREAKDOWN_PATH,
    SELECTED_PATH,
]

for path in required_files:

    if not path.exists():
        raise FileNotFoundError(
            f"Required file not found: {path}"
        )

    print("[OK]", path.name)


if not VISUAL_DIR.exists():
    raise FileNotFoundError(
        f"Visual directory not found: {VISUAL_DIR}"
    )


# ============================================================
# 4. LOAD CSV DATA
# ============================================================

print("\n" + "=" * 80)
print("2. LOAD AUDIT DATA")
print("=" * 80)

manifest = pd.read_csv(
    MANIFEST_PATH
)

audit_summary = pd.read_csv(
    AUDIT_SUMMARY_PATH
)

audit_details = pd.read_csv(
    AUDIT_DETAILS_PATH
)

fp_breakdown = pd.read_csv(
    FP_BREAKDOWN_PATH
)

selected_examples = pd.read_csv(
    SELECTED_PATH
)


required_manifest_columns = [
    "model",
    "class_id",
    "class_name",
    "image",
    "rank",
    "tp",
    "fp",
    "fn",
    "output_file",
]

missing = [
    c for c in required_manifest_columns
    if c not in manifest.columns
]

if missing:
    raise RuntimeError(
        "Manifest is missing columns: "
        + ", ".join(missing)
    )


print("Overlay manifest:", len(manifest))
print("Audit image/class rows:", len(audit_summary))
print("Object detail rows:", len(audit_details))
print("FP breakdown rows:", len(fp_breakdown))
print("Selected examples:", len(selected_examples))


if len(manifest) == 0:
    raise RuntimeError(
        "No overlay records found in the manifest."
    )


# ============================================================
# 5. RESOLVE IMAGE PATHS
# ============================================================

print("\n" + "=" * 80)
print("3. VERIFY OVERLAY IMAGES")
print("=" * 80)


def resolve_overlay_path(path_value):

    original_path = Path(str(path_value))

    if original_path.exists():
        return original_path.resolve()

    # Fallback: locate by filename in visual directory.
    candidate = (
        VISUAL_DIR
        / original_path.name
    )

    if candidate.exists():
        return candidate.resolve()

    candidate = (
        VISUAL_DIR
        / Path(str(path_value)).name
    )

    if candidate.exists():
        return candidate.resolve()

    raise FileNotFoundError(
        f"Overlay image not found: {path_value}"
    )


manifest["resolved_image_path"] = [
    str(resolve_overlay_path(x))
    for x in manifest["output_file"]
]


for path in manifest["resolved_image_path"]:

    if not Path(path).exists():
        raise RuntimeError(
            f"Image file missing: {path}"
        )


print(
    "Verified overlay images:",
    len(manifest)
)

total_image_size = sum(
    Path(p).stat().st_size
    for p in manifest["resolved_image_path"]
)

print(
    f"Total image data: "
    f"{total_image_size / 1024**2:.2f} MB"
)


# ============================================================
# 6. DATASET-LEVEL CLASS SUMMARY
# ============================================================

print("\n" + "=" * 80)
print("4. BUILD CLASS SUMMARY")
print("=" * 80)


class_summary = (
    audit_summary
    .groupby(
        [
            "model",
            "class_id",
            "class_name",
        ],
        as_index=False
    )
    .agg({

        "gt": "sum",

        "pred": "sum",

        "tp": "sum",

        "fp": "sum",

        "fn": "sum",

    })
)


class_summary["precision"] = (
    class_summary["tp"]
    / (
        class_summary["tp"]
        + class_summary["fp"]
    ).replace(0, np.nan)
).fillna(0)


class_summary["recall"] = (
    class_summary["tp"]
    / (
        class_summary["tp"]
        + class_summary["fn"]
    ).replace(0, np.nan)
).fillna(0)


class_summary["f1"] = (
    2
    * class_summary["precision"]
    * class_summary["recall"]
    / (
        class_summary["precision"]
        + class_summary["recall"]
    ).replace(0, np.nan)
).fillna(0)


class_summary["error_count"] = (
    class_summary["fp"]
    + class_summary["fn"]
)


class_summary.to_csv(
    REPORT_DIR / "class_error_summary.csv",
    index=False
)


print(
    class_summary.to_string(
        index=False,
        float_format=lambda x: f"{x:.4f}"
    )
)


# ============================================================
# 7. OVERALL MODEL SUMMARY
# ============================================================

overall_summary = (
    class_summary
    .groupby(
        "model",
        as_index=False
    )
    .agg({

        "gt": "sum",

        "pred": "sum",

        "tp": "sum",

        "fp": "sum",

        "fn": "sum",

    })
)


overall_summary["precision"] = (
    overall_summary["tp"]
    / (
        overall_summary["tp"]
        + overall_summary["fp"]
    ).replace(0, np.nan)
).fillna(0)


overall_summary["recall"] = (
    overall_summary["tp"]
    / (
        overall_summary["tp"]
        + overall_summary["fn"]
    ).replace(0, np.nan)
).fillna(0)


overall_summary["f1"] = (
    2
    * overall_summary["precision"]
    * overall_summary["recall"]
    / (
        overall_summary["precision"]
        + overall_summary["recall"]
    ).replace(0, np.nan)
).fillna(0)


# ============================================================
# 8. SUMMARY TABLE TO HTML
# ============================================================

def dataframe_to_html(
    dataframe,
    table_class="data-table",
    float_format="%.4f"
):

    return dataframe.to_html(
        index=False,
        border=0,
        classes=table_class,
        escape=True,
        float_format=lambda x: float_format % x
    )


overall_html = dataframe_to_html(
    overall_summary
)

class_html = dataframe_to_html(
    class_summary
)


fp_html = dataframe_to_html(
    fp_breakdown
)


# ============================================================
# 9. EMBED IMAGES INTO HTML
# ============================================================

print("\n" + "=" * 80)
print("5. EMBED IMAGES")
print("=" * 80)


def file_to_data_uri(path):

    path = Path(path)

    suffix = path.suffix.lower()

    if suffix in [".jpg", ".jpeg"]:
        mime = "image/jpeg"

    elif suffix == ".png":
        mime = "image/png"

    else:
        raise ValueError(
            f"Unsupported image extension: {suffix}"
        )

    with open(path, "rb") as f:
        encoded = base64.b64encode(
            f.read()
        ).decode("ascii")

    return f"data:{mime};base64,{encoded}"


def safe_text(value):

    if pd.isna(value):
        return ""

    return html_lib.escape(
        str(value),
        quote=True
    )


cards_html = []

embedded_bytes = 0

manifest = manifest.sort_values(
    [
        "model",
        "class_id",
        "rank",
    ]
).reset_index(drop=True)


for index, row in manifest.iterrows():

    image_path = Path(
        row["resolved_image_path"]
    )

    image_uri = file_to_data_uri(
        image_path
    )

    embedded_bytes += image_path.stat().st_size

    model_name = safe_text(row["model"])

    class_id = int(row["class_id"])

    class_name = safe_text(row["class_name"])

    image_name = safe_text(row["image"])

    split = safe_text(row["split"])

    rank = int(row["rank"])

    tp = int(row["tp"])
    fp = int(row["fp"])
    fn = int(row["fn"])

    errors = fp + fn

    # Compact search text.
    search_text = (
        f"{row['model']} "
        f"{row['class_name']} "
        f"{row['image']} "
        f"{row['split']}"
    ).lower()

    search_text = safe_text(search_text)

    card = f"""
    <article
        class="case-card"
        data-model="{model_name}"
        data-class="{class_id}"
        data-split="{split}"
        data-search="{search_text}"
        data-errors="{errors}"
    >

        <div class="card-header">

            <div>
                <span class="model-tag">{model_name}</span>
                <span class="class-tag">{class_name}</span>
            </div>

            <span class="rank-tag">Rank #{rank}</span>

        </div>

        <h3>{image_name}</h3>

        <div class="stats">

            <span class="stat tp">
                TP: {tp}
            </span>

            <span class="stat fp">
                FP: {fp}
            </span>

            <span class="stat fn">
                FN: {fn}
            </span>

            <span class="stat total">
                Errors: {errors}
            </span>

        </div>

        <div class="image-container">

            <img
                src="{image_uri}"
                alt="{image_name}"
                class="audit-image"
                loading="lazy"
                onclick="openImageModal(this.src, '{image_name}')"
            />

        </div>

        <div class="card-footer">

            <span>Split: {split}</span>

            <a
                href="{image_uri}"
                download="{model_name}_class{class_id}_rank{rank}.jpg"
                class="download-link"
            >
                Download image
            </a>

        </div>

    </article>
    """

    cards_html.append(card)

    if (index + 1) % 6 == 0:
        print(
            f"Embedded {index + 1}/{len(manifest)} images"
        )


cards_html_string = "\n".join(cards_html)


print(
    f"Embedded image bytes: "
    f"{embedded_bytes / 1024**2:.2f} MB"
)


# ============================================================
# 10. BUILD TEXT NOTES
# ============================================================

notes = []

notes.append(
    "VISUAL ERROR AUDIT - YOLO11 SEGMENTATION\n"
)

notes.append(
    "Operating point: confidence >= 0.40, mask IoU >= 0.50\n"
)

notes.append(
    "Dataset: 268 validation images, 3,042 GT instances\n"
)

notes.append(
    "\nOVERALL SUMMARY\n"
)


for _, row in overall_summary.iterrows():

    notes.append(
        f"\n{row['model']}\n"
        f"GT={int(row['gt'])}, "
        f"Pred={int(row['pred'])}, "
        f"TP={int(row['tp'])}, "
        f"FP={int(row['fp'])}, "
        f"FN={int(row['fn'])}\n"
        f"Precision={row['precision']:.4f}, "
        f"Recall={row['recall']:.4f}, "
        f"F1={row['f1']:.4f}\n"
    )


notes.append(
    "\nPER-CLASS SUMMARY\n"
)


for _, row in class_summary.iterrows():

    notes.append(
        f"\n{row['model']} | {row['class_name']}\n"
        f"GT={int(row['gt'])}, "
        f"TP={int(row['tp'])}, "
        f"FP={int(row['fp'])}, "
        f"FN={int(row['fn'])}, "
        f"F1={row['f1']:.4f}\n"
    )


notes.append(
    "\nSELECTED VISUAL CASES\n"
)


for _, row in selected_examples.iterrows():

    notes.append(
        f"\n{row['model']} | "
        f"{row['class_name']} | "
        f"{row['image']}\n"
        f"GT={int(row['gt'])}, "
        f"Pred={int(row['pred'])}, "
        f"TP={int(row['tp'])}, "
        f"FP={int(row['fp'])}, "
        f"FN={int(row['fn'])}\n"
    )


notes.append(
    "\nInterpretation reminder:\n"
    "FP/FN totals are measured at confidence=0.40 and mask IoU=0.50.\n"
    "They are diagnostic results on the validation set, not independent test results.\n"
)


with open(
    NOTES_PATH,
    "w",
    encoding="utf-8"
) as f:

    f.write("".join(notes))


# ============================================================
# 11. HTML DOCUMENT
# ============================================================

print("\n" + "=" * 80)
print("6. BUILD SELF-CONTAINED HTML")
print("=" * 80)


num_cards = len(manifest)

num_classes = manifest["class_id"].nunique()

num_models = manifest["model"].nunique()

num_images = manifest["image"].nunique()


HTML_DOCUMENT = f"""<!DOCTYPE html>

<html lang="en">

<head>

<meta charset="UTF-8">

<meta name="viewport" content="width=device-width, initial-scale=1.0">

<title>YOLO11 Segmentation - Visual Error Audit</title>

<style>

:root {{
    --background: #f4f6f9;
    --surface: #ffffff;
    --text: #202938;
    --muted: #64748b;
    --border: #dce2ea;
    --primary: #315b91;
    --green: #16834b;
    --red: #cf3434;
    --orange: #c47712;
}}

* {{
    box-sizing: border-box;
}}

body {{
    margin: 0;
    padding: 0;
    background: var(--background);
    color: var(--text);
    font-family: Arial, Helvetica, sans-serif;
    line-height: 1.55;
}}

.container {{
    max-width: 1500px;
    margin: auto;
    padding: 26px;
}}

h1 {{
    margin-bottom: 5px;
    font-size: 30px;
}}

h2 {{
    margin-top: 35px;
    border-bottom: 1px solid var(--border);
    padding-bottom: 9px;
}}

.subtitle {{
    color: var(--muted);
}}

.metrics-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin: 24px 0;
}}

.metric-box {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 17px;
}}

.metric-label {{
    color: var(--muted);
    font-size: 13px;
}}

.metric-value {{
    font-size: 26px;
    font-weight: bold;
    margin-top: 5px;
}}

.section-note {{
    color: var(--muted);
    background: white;
    padding: 13px 16px;
    border-left: 4px solid var(--primary);
    border-radius: 5px;
    margin: 15px 0;
}}

.table-wrap {{
    overflow-x: auto;
    background: white;
    border-radius: 9px;
    border: 1px solid var(--border);
    margin: 15px 0;
}}

.data-table {{
    border-collapse: collapse;
    width: 100%;
    font-size: 13px;
    min-width: 700px;
}}

.data-table th,
.data-table td {{
    border-bottom: 1px solid var(--border);
    padding: 10px;
    text-align: right;
    white-space: nowrap;
}}

.data-table th {{
    background: #edf2f8;
    position: sticky;
    top: 0;
}}

.data-table td:first-child,
.data-table th:first-child {{
    text-align: left;
}}

.filters {{
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    padding: 16px;
    background: white;
    border: 1px solid var(--border);
    border-radius: 10px;
    margin: 20px 0;
}}

.filters input,
.filters select {{
    padding: 10px;
    border: 1px solid var(--border);
    border-radius: 6px;
    min-width: 160px;
    background: white;
    font-size: 14px;
}}

.case-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(420px, 1fr));
    gap: 18px;
    margin-top: 20px;
}}

.case-card {{
    background: white;
    border: 1px solid var(--border);
    border-radius: 10px;
    overflow: hidden;
    box-shadow: 0 2px 6px rgba(0,0,0,0.04);
}}

.card-header {{
    padding: 14px 15px 5px;
    display: flex;
    justify-content: space-between;
    gap: 8px;
    flex-wrap: wrap;
}}

.model-tag {{
    display: inline-block;
    font-size: 12px;
    font-weight: bold;
    color: #234b7d;
    background: #e4edf8;
    padding: 5px 8px;
    border-radius: 5px;
}}

.class-tag {{
    display: inline-block;
    margin-left: 5px;
    font-size: 12px;
    color: #46566b;
    background: #edf0f4;
    padding: 5px 8px;
    border-radius: 5px;
}}

.rank-tag {{
    color: var(--muted);
    font-size: 12px;
}}

.case-card h3 {{
    font-size: 14px;
    padding: 0 15px;
    overflow-wrap: anywhere;
}}

.stats {{
    display: flex;
    flex-wrap: wrap;
    gap: 7px;
    padding: 0 15px 12px;
}}

.stat {{
    font-size: 12px;
    padding: 4px 8px;
    border-radius: 5px;
    background: #f1f3f6;
}}

.stat.tp {{
    color: var(--green);
}}

.stat.fp {{
    color: var(--orange);
}}

.stat.fn {{
    color: var(--red);
}}

.stat.total {{
    font-weight: bold;
}}

.image-container {{
    background: #151a22;
    padding: 8px;
}}

.audit-image {{
    display: block;
    width: 100%;
    height: auto;
    cursor: zoom-in;
    border-radius: 3px;
}}

.card-footer {{
    padding: 10px 15px;
    display: flex;
    justify-content: space-between;
    color: var(--muted);
    font-size: 12px;
}}

.download-link {{
    color: var(--primary);
    text-decoration: none;
    font-weight: bold;
}}

.download-link:hover {{
    text-decoration: underline;
}}

.legend {{
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
    margin: 15px 0;
    background: white;
    border: 1px solid var(--border);
    padding: 14px;
    border-radius: 8px;
}}

.legend-item {{
    display: flex;
    align-items: center;
    gap: 7px;
    font-size: 13px;
}}

.color-box {{
    width: 15px;
    height: 15px;
    border-radius: 3px;
}}

#resultCount {{
    color: var(--muted);
    font-weight: bold;
    padding: 5px 0;
}}

.modal {{
    display: none;
    position: fixed;
    z-index: 1000;
    inset: 0;
    background: rgba(0,0,0,0.94);
    padding: 25px;
    overflow: auto;
}}

.modal-content {{
    display: block;
    max-width: 96%;
    max-height: 90vh;
    object-fit: contain;
    margin: 30px auto;
    cursor: zoom-out;
}}

.modal-caption {{
    color: white;
    text-align: center;
    margin-top: 10px;
}}

.modal-close {{
    position: fixed;
    top: 14px;
    right: 25px;
    color: white;
    font-size: 38px;
    cursor: pointer;
}}

.hidden {{
    display: none !important;
}}

footer {{
    margin: 50px 0 20px;
    padding-top: 15px;
    border-top: 1px solid var(--border);
    color: var(--muted);
    font-size: 12px;
}}

@media(max-width: 600px) {{

    .container {{
        padding: 12px;
    }}

    .case-grid {{
        grid-template-columns: 1fr;
    }}

    h1 {{
        font-size: 23px;
    }}

}}

</style>

</head>


<body>

<div class="container">

    <header>

        <h1>YOLO11 Segmentation - Visual Error Audit</h1>

        <div class="subtitle">
            C-IRFS vs CB-IRFS | Validation Error Analysis
        </div>

    </header>


    <div class="section-note">

        <strong>Evaluation configuration</strong><br>

        Dataset: 268 images, 3,042 Ground Truth instances<br>

        Confidence threshold: 0.40<br>

        Mask IoU threshold: 0.50<br>

        Classes: 6<br>

        Selected examples: top 2 images per model and class

    </div>


    <div class="metrics-grid">

        <div class="metric-box">

            <div class="metric-label">
                Embedded overlays
            </div>

            <div class="metric-value">
                {num_cards}
            </div>

        </div>


        <div class="metric-box">

            <div class="metric-label">
                Models
            </div>

            <div class="metric-value">
                {num_models}
            </div>

        </div>


        <div class="metric-box">

            <div class="metric-label">
                Classes represented
            </div>

            <div class="metric-value">
                {num_classes}
            </div>

        </div>


        <div class="metric-box">

            <div class="metric-label">
                Unique image names
            </div>

            <div class="metric-value">
                {num_images}
            </div>

        </div>

    </div>


    <h2>1. Overall model summary</h2>

    <div class="table-wrap">
        {overall_html}
    </div>


    <h2>2. Per-class error summary</h2>

    <div class="section-note">

        The statistics below use the full validation set,
        not only the selected visual examples.

    </div>

    <div class="table-wrap">
        {class_html}
    </div>


    <h2>3. False-positive categories</h2>

    <div class="table-wrap">
        {fp_html}
    </div>


    <h2>4. Visual legend</h2>

    <div class="legend">

        <div class="legend-item">
            <div class="color-box" style="background:#00C800"></div>
            GT matched
        </div>

        <div class="legend-item">
            <div class="color-box" style="background:#FF0000"></div>
            GT false negative
        </div>

        <div class="legend-item">
            <div class="color-box" style="background:#00FFFF"></div>
            Prediction matched
        </div>

        <div class="legend-item">
            <div class="color-box" style="background:#FFA500"></div>
            Prediction false positive
        </div>

    </div>


    <h2>5. Visual error cases</h2>

